package vip.xiaonuo.srm.quality;
import java.util.*;import java.math.*;import java.time.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import org.springframework.scheduling.annotation.Scheduled;import vip.xiaonuo.srm.api.SrmSupplierAccessApi.Context;import vip.xiaonuo.srm.performance.api.SrmQualityIngressApi;import vip.xiaonuo.srm.exchange.api.SrmExchangeApi;import vip.xiaonuo.srm.performance.*;import static vip.xiaonuo.srm.quality.QualityStore.*;import static vip.xiaonuo.srm.quality.QualityInputs.*;
@Service @RequiredArgsConstructor @Transactional(isolation=Isolation.READ_COMMITTED) public class QualitySources implements SrmQualityIngressApi {
 final QualityStore x;final SrmExchangeApi exchange;final PerformanceService performance;
 public void map(Context a,Mapping p){require(!a.portal()&&x.has(a,"superAdmin","SYS-ADMIN"),403,"仅系统管理员可配置QMS映射");var supplier=x.access.requireSupplier(a,p.supplierId(),true);require(supplier.orgId().equals(a.orgId()),403,"只能映射当前组织");var c=x.db.queryForMap("SELECT MODE FROM SRM_XCH_CONNECTOR WHERE ID=?",p.connectorId());exchange.requireTarget(p.connectorId(),a.orgId(),"QMS",s(c,"MODE"));var old=x.db.queryForList("SELECT SUPPLIER_ID FROM SRM_QL_SOURCE_MAP WHERE CONNECTOR_ID=? AND EXTERNAL_KEY=? FOR UPDATE",p.connectorId(),p.externalKey());require(old.isEmpty()||s(old.get(0),"SUPPLIER_ID").equals(p.supplierId()),409,"不可静默更换来源供方映射");x.db.update("INSERT IGNORE INTO SRM_QL_SOURCE_MAP VALUES(?,?,?,?,?,NOW(3))",p.connectorId(),p.externalKey(),a.orgId(),p.supplierId(),a.userId());}
 public List<Map<String,Object>> mappings(Context a){x.sqe(a);return x.db.queryForList("SELECT m.CONNECTOR_ID AS connectorId,m.EXTERNAL_KEY AS externalKey,m.SUPPLIER_ID AS supplierId,s.NAME AS supplierName FROM SRM_QL_SOURCE_MAP m JOIN SRM_SUPPLIER s ON s.ID=m.SUPPLIER_ID WHERE m.ORG_ID=? ORDER BY m.EXTERNAL_KEY",a.orgId());}
 String mapped(Origin o,String key){String table=o.system().equals("QMS")?"SRM_QL_SOURCE_MAP":"SRM_COL_SUPPLIER_MAP";var rows=x.db.queryForList("SELECT SUPPLIER_ID FROM "+table+" WHERE CONNECTOR_ID=? AND EXTERNAL_KEY=? AND ORG_ID=?",o.connectorId(),key,o.orgId());if(rows.isEmpty())throw new vip.xiaonuo.srm.collaboration.api.SrmCollaborationIngressApi.PendingDependency("QUALITY_SUPPLIER_MAPPING_REQUIRED");return s(rows.get(0),"SUPPLIER_ID");}
 public Map<String,Object> apply(Origin o,String resource,String key,long version,Map<String,Object> data){var a=x.system(o.orgId(),o.operatorId());if(resource.equals("QMS_INSPECTION")){require(o.system().equals("QMS"),403,"检验记录只能由QMS提交");var p=x.input(data,Inspection.class);PerformanceRules.period(p.period());String sid=mapped(o,p.supplierKey());x.access.requireSupplier(a,sid,true);var old=x.db.queryForList("SELECT * FROM SRM_QL_INSPECTION WHERE CONNECTOR_ID=? AND EXTERNAL_KEY=? FOR UPDATE",o.connectorId(),key);if(!old.isEmpty())require(s(old.get(0),"SUPPLIER_ID").equals(sid)&&s(old.get(0),"PERIOD").equals(p.period())&&n(old.get(0),"SOURCE_VERSION")+1==version,409,"检验记录身份或版本不一致");var policy=x.policy(o.orgId());BigDecimal deduction=p.result().equals("PASS")?BigDecimal.ZERO:new BigDecimal(String.valueOf(policy.get(switch(p.severity()){case "SEVERE"->"severeDeduction";case "MAJOR"->"majorDeduction";default->"minorDeduction";})));String id=old.isEmpty()?id():s(old.get(0),"ID");x.db.update("INSERT INTO SRM_QL_INSPECTION(ID,ORG_ID,SUPPLIER_ID,CONNECTOR_ID,EXTERNAL_KEY,SOURCE_VERSION,MODE,PERIOD,RESULT,SEVERITY,DEDUCTION,POLICY_VERSION,PAYLOAD_CIPHER,CREATED_BY,CREATED_AT,UPDATED_AT) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE SOURCE_VERSION=VALUES(SOURCE_VERSION),RESULT=VALUES(RESULT),SEVERITY=VALUES(SEVERITY),DEDUCTION=VALUES(DEDUCTION),POLICY_VERSION=VALUES(POLICY_VERSION),PAYLOAD_CIPHER=VALUES(PAYLOAD_CIPHER),UPDATED_AT=NOW(3)",id,o.orgId(),sid,o.connectorId(),key,version,o.mode(),p.period(),p.result(),p.severity(),deduction,policy.get("version"),x.crypto.encrypt(x.json(p)),o.operatorId());if(p.result().equals("FAIL")&&p.severity().equals("SEVERE"))x.event(a,sid,"SEVERE_QUALITY","qms:"+o.connectorId()+":"+key+":"+version,"QMS",Map.of("inspectionId",id,"sourceRef",p.sourceRef(),"period",p.period(),"description",p.description(),"mode",o.mode()));return Map.of("id",id,"deduction",deduction);}
  require(resource.equals("ERP_PERFORMANCE")&&o.system().equals("ERP"),403,"绩效基础项只能由ERP提交");var p=x.input(data,ErpScores.class);PerformanceRules.period(p.period());PerformanceRules.scores(p.scores());require(key.equals(p.supplierKey()+":"+p.period()),400,"ERP绩效业务键不一致");String sid=mapped(o,p.supplierKey());x.access.requireSupplier(a,sid,true);x.db.update("INSERT INTO SRM_QL_ERP_SCORE VALUES(?,?,?,?,?,?,?,NOW(3)) ON DUPLICATE KEY UPDATE SOURCE_VERSION=VALUES(SOURCE_VERSION),PAYLOAD_CIPHER=VALUES(PAYLOAD_CIPHER),UPDATED_AT=NOW(3)",o.connectorId(),sid,o.orgId(),p.period(),o.mode(),version,x.crypto.encrypt(x.json(p)));return Map.of("staged",true);
 }
 public Map<String,Object> preview(Context a,String sid,String period,String mode){x.sqe(a);var supplier=x.access.requireSupplier(a,sid,false);PerformanceRules.period(period);require(Set.of("SANDBOX","LIVE").contains(mode),400,"来源模式无效");var erps=x.db.queryForList("SELECT * FROM SRM_QL_ERP_SCORE WHERE SUPPLIER_ID=? AND ORG_ID=? AND PERIOD=? AND MODE=? ORDER BY CONNECTOR_ID",sid,supplier.orgId(),period,mode);var qms=x.db.queryForList("SELECT ID,SOURCE_VERSION,DEDUCTION,POLICY_VERSION,CONNECTOR_ID,RESULT,SEVERITY FROM SRM_QL_INSPECTION WHERE SUPPLIER_ID=? AND PERIOD=? AND MODE=? ORDER BY ID",sid,period,mode);var out=new LinkedHashMap<String,Object>();out.put("supplierId",sid);out.put("period",period);out.put("mode",mode);out.put("ready",erps.size()==1&&!qms.isEmpty());out.put("inspections",qms);out.put("rule","quality-v1: max(0,100 - sum(current inspection deductions)); delivery/cost/service from authenticated ERP");if(erps.size()!=1||qms.isEmpty()){out.put("notice","需要同一模式下唯一ERP基础数据和至少一条QMS检验，不以零分或满分代替缺失来源");return out;}var erp=erps.get(0);var source=x.object(x.crypto.decrypt(s(erp,"PAYLOAD_CIPHER")));List<?> raw=(List<?>)source.get("scores");var scores=new ArrayList<BigDecimal>();for(Object v:raw)scores.add(new BigDecimal(String.valueOf(v)));BigDecimal penalty=qms.stream().map(r->new BigDecimal(String.valueOf(r.get("DEDUCTION")))).reduce(BigDecimal.ZERO,BigDecimal::add);scores.set(1,QualityRules.qualityScore(qms.stream().map(r->new BigDecimal(String.valueOf(r.get("DEDUCTION")))).toList()));var basis=Map.of("erpConnector",erp.get("CONNECTOR_ID"),"erpVersion",erp.get("SOURCE_VERSION"),"erpSourceRef",source.get("sourceRef"),"qms",qms,"scores",scores,"period",period,"mode",mode,"rule","quality-v1");out.put("scores",scores);out.put("basisHash",x.hash(basis));out.put("basis",basis);return out;}
 public Map<String,Object> publish(Context a,Publish p){x.sqe(a);x.access.requireSupplier(a,p.supplierId(),true);var preview=preview(a,p.supplierId(),p.period(),p.mode());require(Boolean.TRUE.equals(preview.get("ready"))&&p.basisHash().equals(preview.get("basisHash")),409,"来源不足或依据变化，请重新预览");var prior=x.db.queryForList("SELECT INPUT_ID FROM SRM_QL_SCORE_PUBLICATION WHERE SUPPLIER_ID=? AND PERIOD=? AND BASIS_HASH=?",p.supplierId(),p.period(),p.basisHash());if(!prior.isEmpty())return Map.of("inputId",prior.get(0).get("INPUT_ID"),"replayed",true);var values=((List<?>)preview.get("scores")).stream().map(v->new BigDecimal(String.valueOf(v))).toList();var r=performance.recordTrustedSource(a,p.supplierId(),p.period(),values,p.mode(),"QUALITY:"+p.basisHash());var supplier=x.access.requireSupplier(a,p.supplierId(),false);x.db.update("INSERT INTO SRM_QL_SCORE_PUBLICATION VALUES(?,?,?,?,?,?,?,NOW(3))",id(),supplier.orgId(),p.supplierId(),p.period(),p.basisHash(),r.get("inputId"),p.mode());return r;}
 public Map<String,Object> demo(Context a,Demo p){x.sqe(a);var supplier=x.access.requireSupplier(a,p.supplierId(),true);require(supplier.orgId().equals(a.orgId()),403,"只可操作当前组织沙箱");PerformanceRules.period(p.period());var target=exchange.targets(a.orgId(),p.system().equals("QMS")?"QMS":"ERP","SANDBOX");require(target.size()==1,503,"本机来源连接未配置");String table=p.system().equals("QMS")?"SRM_QL_SOURCE_MAP":"SRM_COL_SUPPLIER_MAP";var rows=x.db.queryForList("SELECT EXTERNAL_KEY FROM "+table+" WHERE CONNECTOR_ID=? AND SUPPLIER_ID=?",target.get(0).get("id"),p.supplierId());require(rows.size()==1,409,"来源供方须唯一映射");String out=exchange.enqueue(a.orgId(),p.system().equals("QMS")?"QMS":"ERP","SANDBOX","SANDBOX_QUALITY_SOURCE",p.requestKey(),1,Map.of("system",p.system(),"supplierKey",rows.get(0).get("EXTERNAL_KEY"),"period",p.period(),"result",p.result(),"severity",p.severity()),a.userId());return Map.of("outboxId",out,"mode","SANDBOX");}
}
